def resume(state_token, input_responses, now):
    state = signer.verify(state_token, now)
    response = input_responses.get('approval')
    if response is None: return request_input_again(state)
    if response['action'] in {'decline', 'cancel'}: return {'status': 'CANCELLED'}
    if not isinstance(response['content'].get('approved'), bool):
        raise ValueError('approved must be boolean')
    return {'status': 'APPROVED_FOR_REVIEW'} if response['content']['approved'] else {'status': 'REJECTED'}
